use std::fs;
use std::path::Path;

fn fail(c:i32)->i32 { fs::create_dir_all("/app/kegbay").ok(); fs::write("/app/kegbay/MARK","false").ok(); c }
fn read_pairs() -> Vec<(String,u64)> {
    fs::read_to_string("/app/kegbay/pairs.tmp").unwrap_or_default().lines().filter_map(|line| {
        let mut p=line.split('\t');
        Some((p.next()?.to_string(),p.next()?.parse().ok()?))
    }).collect()
}
pub fn finish() -> i32 {
    let pairs=read_pairs();
    let names=match crate::fold::rib_c(&pairs,None) { Ok(x)=>x,Err(c)=>return fail(c) };
    let mut body=String::new();
    for (i,n) in names.iter().enumerate() {
        let m=crate::parse::load(n);
        body.push_str(&format!("{}\t{}\t{}\n",i+1,n,crate::parse::guid_hex(&m.guid)));
    }
    if fs::write("/app/kegbay/ribbon.txt",body).is_err() { return fail(1); }
    0
}
fn json_escape(s:&str)->String {
    let mut o=String::new();
    for c in s.chars() { match c { '"'=>o.push_str("\\\""),'\\'=>o.push_str("\\\\"),'\n'=>o.push_str("\\n"),'\r'=>o.push_str("\\r"),'\t'=>o.push_str("\\t"), c if c<' '=>o.push_str(&format!("\\u{:04x}",c as u32)),c=>o.push(c) } }
    o
}
pub fn pour() -> i32 {
    let root=std::env::args().nth(2).unwrap_or_else(||"/app/dropwell".to_string());
    let current=match crate::walk::rib_a() { Ok(x)=>x,Err(c)=>return fail(c) };
    let dummy:Vec<(String,u64)>=current.iter().map(|x|(x.clone(),0)).collect();
    if let Err(c)=crate::fold::rib_c(&dummy,Some(&root)) { return fail(c); }
    let ribbon=match fs::read_to_string("/app/kegbay/ribbon.txt") { Ok(x)=>x,Err(_)=>return fail(1) };
    let mut rows:Vec<(u32,String,String,String)>=Vec::new();
    let mut seen=HashSet::new();
    for line in ribbon.lines() {
        let p:Vec<&str>=line.split('\t').collect();
        if p.len()!=3 { return fail(1); }
